package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarFileStoreMutaGate1Test {

  @TempDir
  Path tempDir;

  @Test
  void nameReturnsOnlyTheFileNameOfTheTarFile() throws Exception {
    Path dir = Files.createDirectory(tempDir.resolve("some-parent-dir"));
    Path tar = dir.resolve("my archive.tar");
    Files.write(tar, new byte[1024]);

    TarFileSystem fs = new TarFileSystem(new TarFileSystemProvider(), tar.toUri(), tar);
    TarFileStore store = new TarFileStore(fs);

    String name = store.name();

    assertEquals("my archive.tar", name);
    assertNotEquals(tar.toString(), name);
    assertEquals(tar.getFileName().toString(), name);
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate2Test {

  @Test
  void typeReturnsTarRegardlessOfFileSystemAndIsStable() {
    TarFileStore store = new TarFileStore(null);

    String first = store.type();
    String second = store.type();

    assertEquals("tar", first);
    assertEquals(5 - 2, first.length());
    assertEquals("tar", second);
    assertSame(first, second);
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate3Test {

  @Test
  void isReadOnlyIsTrueRegardlessOfBackingFileSystemAndRepeatedCalls() {
    TarFileStore first = new TarFileStore(null);
    TarFileStore second = new TarFileStore(null);

    assertTrue(first.isReadOnly());
    assertTrue(first.isReadOnly());
    assertTrue(second.isReadOnly());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarFileStoreMutaGate4Test {

  @TempDir
  Path tempDir;

  @Test
  void getTotalSpaceReflectsCurrentSizeOfTarFile() throws Exception {
    Path tar = tempDir.resolve("sample.tar");
    Files.write(tar, new byte[1234]);

    TarFileSystem fs = new TarFileSystem(new TarFileSystemProvider(), tar.toUri(), tar);
    TarFileStore store = new TarFileStore(fs);

    assertEquals(1234L, store.getTotalSpace());

    Files.write(tar, new byte[5000]);
    assertEquals(5000L, store.getTotalSpace());

    Files.write(tar, new byte[0]);
    assertEquals(0L, store.getTotalSpace());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate5Test {

  @Test
  void usableSpaceIsZeroAndDoesNotDependOnFileSystem() throws IOException {
    TarFileStore store = new TarFileStore(null);

    assertEquals(0L, store.getUsableSpace());
    assertEquals(0L, store.getUsableSpace());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate6Test {

  @Test
  void getUnallocatedSpaceIsAlwaysZeroAndDoesNotTouchFileSystem() throws IOException {
    // The file system is never consulted, so a null file system must not matter.
    TarFileStore store = new TarFileStore(null);

    assertEquals(0L, store.getUnallocatedSpace());
    // Repeated calls give the same result.
    assertEquals(0L, store.getUnallocatedSpace());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.attribute.AclFileAttributeView;
import java.nio.file.attribute.BasicFileAttributeView;
import java.nio.file.attribute.DosFileAttributeView;
import java.nio.file.attribute.FileAttributeView;
import java.nio.file.attribute.FileOwnerAttributeView;
import java.nio.file.attribute.PosixFileAttributeView;
import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate7Test {

  interface CustomBasicView extends BasicFileAttributeView {}

  interface UnrelatedView extends FileAttributeView {}

  @Test
  void supportsFileAttributeViewByClassChecksBasicAssignability() {
    TarFileStore store = new TarFileStore(null);

    assertFalse(store.supportsFileAttributeView((Class<? extends FileAttributeView>) null));

    assertTrue(store.supportsFileAttributeView(BasicFileAttributeView.class));

    assertTrue(store.supportsFileAttributeView(PosixFileAttributeView.class));
    assertTrue(store.supportsFileAttributeView(DosFileAttributeView.class));
    assertTrue(store.supportsFileAttributeView(CustomBasicView.class));

    assertFalse(store.supportsFileAttributeView(FileAttributeView.class));
    assertFalse(store.supportsFileAttributeView(FileOwnerAttributeView.class));
    assertFalse(store.supportsFileAttributeView(AclFileAttributeView.class));
    assertFalse(store.supportsFileAttributeView(UnrelatedView.class));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate8Test {

  @Test
  void supportsFileAttributeViewByNameOnlyAcceptsExactBasic() {
    TarFileStore store = new TarFileStore(null);

    assertTrue(store.supportsFileAttributeView("basic"));

    assertFalse(store.supportsFileAttributeView("posix"));
    assertFalse(store.supportsFileAttributeView("unix"));
    assertFalse(store.supportsFileAttributeView("owner"));
    assertFalse(store.supportsFileAttributeView("dos"));
    assertFalse(store.supportsFileAttributeView("BASIC"));
    assertFalse(store.supportsFileAttributeView("Basic"));
    assertFalse(store.supportsFileAttributeView(" basic"));
    assertFalse(store.supportsFileAttributeView("basic "));
    assertFalse(store.supportsFileAttributeView("basic:size"));
    assertFalse(store.supportsFileAttributeView(""));
    assertFalse(store.supportsFileAttributeView((String) null));
  }
}

